import { disablePageScroll, enablePageScroll} from 'scroll-lock/dist/scroll-lock.js';

export function aboutInit () {
  const btnOpen = document.querySelector('.screen2__btn');
  const btnClose = document.querySelector('.about__btn');
  const about = document.querySelector('.about');

  btnOpen.addEventListener('click', (e) => {
    about.classList.add('active');
    disablePageScroll(about);
  })

  btnClose.addEventListener('click', (e) => {
    if (e.target.closest('.about__btn')) {
      about.classList.remove('active');
      enablePageScroll();
    }
  })

  window.addEventListener('resize', (e) => {
    about.classList.remove('active');
    enablePageScroll();
  })
}