import { disablePageScroll, enablePageScroll } from 'scroll-lock';

export function popUpsInit () {
  const btnsOpen = document.querySelectorAll('[data-btn="request"]');
  const btnCall = document.querySelector('.header__phone');
  const modalForm = document.querySelector('.modal-form');
  const btnClose = document.querySelector('.header__cross');
  const modalSuccess = document.querySelector('.modal-success');

  btnsOpen.forEach(btn => {
    btn.addEventListener('click', (e) => {
      modalForm.classList.toggle('active');
      const isActive = modalForm.classList.contains('active');

      if (isActive) {
        setTimeout(() => {
          disablePageScroll();
          btnClose.classList.add('active');
          btnCall.classList.add('off');
        }, 300)
      }
      else {
        enablePageScroll();
        btnClose.classList.remove('active');
        btnCall.classList.remove('off');
      }
    })
  })

  window.addEventListener('resize', (e) => {
    modalForm.classList.remove('active');
    enablePageScroll();
    btnClose.classList.remove('active');
    btnCall.classList.remove('off');
  })


}